namespace Scheduling;

/// <summary>Places jobs onto the most suitable available resource.</summary>
public sealed class Scheduler
{
    public IReadOnlyList<string> PlaceJobs(IEnumerable<Job> jobs, IReadOnlyList<Resource> resources)
    {
        var placements = new List<string>();
        foreach (var job in jobs)
        {
            var placement = PlaceJob(job, resources);
            if (placement != null)
                placements.Add(placement);
        }

        return placements;
    }

    private static string? PlaceJob(Job job, IReadOnlyList<Resource> resources)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;

        var chosen = ChooseResource(job.RequiredSkill, resources);
        if (chosen == null)
            return $"{job.Id}:UNPLACED";

        return FormatPlacement(job, chosen);
    }

    private static Resource? ChooseResource(
        string requiredSkill,
        IReadOnlyList<Resource> resources)
    {
        Resource? chosen = null;
        foreach (var resource in resources)
        {
            if (!resource.Skills.Contains(requiredSkill))
                continue;
            if (resource.Calendar.Count > 20)
                continue;
            if (chosen == null || resource.Calendar.Count < chosen.Calendar.Count)
                chosen = resource;
        }

        return chosen;
    }

    private static string FormatPlacement(Job job, Resource chosen)
    {
        bool overtime = false;
        if (job.Priority > 5 && chosen.Calendar.Count > 10)
            overtime = true;
        if (job.Duration.TotalHours > 8)
            overtime = true;

        if (overtime)
            return $"{job.Id}:{chosen.Name}:OT";
        if (job.Priority > 8)
            return $"{job.Id}:{chosen.Name}:URGENT";
        return $"{job.Id}:{chosen.Name}";
    }
}
